# Expected values are SymPy's outputs for the same calls (Inverse Laplace transforms).

skip_unless_full_tests()

skip_on_cran()

s <- Symbol("s"); k <- Symbol("k", real = TRUE); n <- Symbol("n", real = TRUE); t <- Symbol("t", real = TRUE); x <- Symbol("x", real = TRUE)
a <- Symbol("a", positive = TRUE); b <- Symbol("b", positive = TRUE); c <- Symbol("c", positive = TRUE); d <- Symbol("d", positive = TRUE)
f <- Function("f"); F <- Function("F")
mi_fmt <- function(v) if (is.null(v)) "None" else if (is_sym(v)) gsub("\n", " ", sstr(v)) else paste0("(", paste(vapply(v, function(z) gsub("\n", " ", sstr(z)), ""), collapse = ", "), ")")

test_that("Inverse Laplace transforms match SymPy", {
  expect_equal(mi_fmt(inverse_laplace_transform(2, s, t)), "2*DiracDelta(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / s, s, t)), "Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / s ^ 2, s, t)), "t*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / s ^ 5, s, t)), "t^4*Heaviside(t)/24")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / s ^ n, s, t)), "t^(n - 1)*Heaviside(t)/gamma(n)")
  expect_equal(mi_fmt(inverse_laplace_transform(a / (a + s), s, t)), "a*exp(-a*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(s / (a + s), s, t)), "-a*exp(-a*t)*Heaviside(t) + DiracDelta(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(b * s / (s + a) ^ 2, s, t)), "b*(-a*t*exp(-a*t)*Heaviside(t) + exp(-a*t)*Heaviside(t))")
  expect_equal(mi_fmt(inverse_laplace_transform(c / ((s + a) * (s + b)), s, t, simplify = TRUE)), "c*(exp(a*t) - exp(b*t))*exp(-t*(a + b))*Heaviside(t)/(a - b)")
  expect_equal(mi_fmt(inverse_laplace_transform(c * s / ((s + a) * (s + b)), s, t, simplify = TRUE)), "c*(a*exp(b*t) - b*exp(a*t))*exp(-t*(a + b))*Heaviside(t)/(a - b)")
  expect_equal(mi_fmt(inverse_laplace_transform(s / (a + s) ^ 3, s, t, simplify = TRUE)), "t*(-a*t + 2)*exp(-a*t)*Heaviside(t)/2")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (s * (a + s) ^ 3), s, t, simplify = TRUE)), "(-a^2*t^2 - 2*a*t + 2*exp(a*t) - 2)*exp(-a*t)*Heaviside(t)/(2*a^3)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (s * (a + s) ^ n), s, t)), "Heaviside(t)*lowergamma(n, a*t)/(a^n*gamma(n))")
  expect_equal(mi_fmt(inverse_laplace_transform((s - a) ^ (-b), s, t)), "t^(b - 1)*exp(a*t)*Heaviside(t)/gamma(b)")
  expect_equal(mi_fmt(inverse_laplace_transform((a + s) ^ (-2), s, t)), "t*exp(-a*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((a + s) ^ (-5), s, t)), "t^4*exp(-a*t)*Heaviside(t)/24")
  expect_equal(mi_fmt(inverse_laplace_transform(s ^ 2 / (s ^ 2 + 1), s, t)), "-sin(t)*Heaviside(t) + DiracDelta(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 - 1 / (s ^ 2 + 1), s, t)), "-sin(t)*Heaviside(t) + DiracDelta(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(a / (a ^ 2 + s ^ 2), s, t)), "sin(a*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(s / (s ^ 2 + a ^ 2), s, t)), "cos(a*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(b / (b ^ 2 + (a + s) ^ 2), s, t)), "exp(-a*t)*sin(b*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(b * s / (b ^ 2 + (a + s) ^ 2), s, t)), "b*(-a*exp(-a*t)*sin(b*t)/b + exp(-a*t)*cos(b*t))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (s ^ 2 * (s ^ 2 + 1)), s, t)), "t*Heaviside(t) - sin(t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(c * s / (d ^ 2 * (s + a) ^ 2 + b ^ 2), s, t, simplify = TRUE)), "c*(-a*d*sin(b*t/d) + b*cos(b*t/d))*exp(-a*t)*Heaviside(t)/(b*d^2)")
  expect_equal(mi_fmt(inverse_laplace_transform((b * s ^ 2 + d) / (a ^ 2 + s ^ 2) ^ 2, s, t, simplify = TRUE)), "(2*a^2*b*sin(a*t) + (a^2*b - d)*(a*t*cos(a*t) - sin(a*t)))*Heaviside(t)/(2*a^3)")
  expect_equal(mi_fmt(inverse_laplace_transform(b / (s ^ 2 - a ^ 2), s, t, simplify = TRUE)), "b*sinh(a*t)*Heaviside(t)/a")
  expect_equal(mi_fmt(inverse_laplace_transform(b / (s ^ 2 - a ^ 2), s, t)), "b*(exp(a*t)*Heaviside(t)/(2*a) - exp(-a*t)*Heaviside(t)/(2*a))")
  expect_equal(mi_fmt(inverse_laplace_transform(b * s / (s ^ 2 - a ^ 2), s, t, simplify = TRUE)), "b*cosh(a*t)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(b / (s * (s + a)), s, t)), "b*(Heaviside(t)/a - exp(-a*t)*Heaviside(t)/a)")
  expect_equal(mi_fmt(inverse_laplace_transform((s + 8) / ((s + 2) * (s ^ 2 + 2 * s + 10)), s, t, simplify = TRUE)), "((8*sin(3*t) - 9*cos(3*t))*exp(t) + 9)*exp(-2*t)*Heaviside(t)/15")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (a * s ^ 2 + b * s + c), s, t)), "2*exp(-b*t/(2*a))*sin(t*sqrt(4*a*c - b^2)/(2*a))*Heaviside(t)/sqrt(4*a*c - b^2)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s) / (b * s - a), s, t)), "exp(a*t/b)*Heaviside(t)*erf(sqrt(a)*sqrt(t)/sqrt(b))/(sqrt(a)*sqrt(b))")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(k * s) / (c * s - a) / s, s, t)), "(-2*c*sqrt(t)/(sqrt(pi)*a) + c^(3/2)*exp(a*t/c)*erf(sqrt(a)*sqrt(t)/sqrt(c))/a^(3/2))*Heaviside(t)/(c*sqrt(k))")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (sqrt(c * s) + a), s, t)), "(-a*exp(a^2*t/c)*erfc(a*sqrt(t)/sqrt(c))/c + 1/(sqrt(pi)*sqrt(c)*sqrt(t)))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(a / s / (b * sqrt(s) + a), s, t)), "(-exp(a^2*t/b^2)*erfc(a*sqrt(t)/b) + 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((a - b) * sqrt(s) / (sqrt(s) + sqrt(a)) / (s - b), s, t)), "(sqrt(a)*sqrt(b)*exp(b*t)*erfc(sqrt(b)*sqrt(t)) + a*exp(a*t)*erfc(sqrt(a)*sqrt(t)) - b*exp(b*t))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s) / (sqrt(b * s) + a), s, t)), "exp(a^2*t/b)*Heaviside(t)*erfc(a*sqrt(t)/sqrt(b))/sqrt(b)")
  expect_equal(mi_fmt(inverse_laplace_transform(a ^ 2 / (sqrt(s) + a) / s ^ (as_sym(3) / 2), s, t)), "(2*a*sqrt(t)/sqrt(pi) + exp(a^2*t)*erfc(a*sqrt(t)) - 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((a - b) * sqrt(b) / (s - b) / sqrt(s) / (sqrt(s) + sqrt(a)), s, t)), "(sqrt(a)*exp(b*t)*erf(sqrt(b)*sqrt(t)) + sqrt(b)*exp(a*t)*erfc(sqrt(a)*sqrt(t)) - sqrt(b)*exp(b*t))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (sqrt(s) + sqrt(a)) ^ 2, s, t)), "(-2*sqrt(a)*sqrt(t)/sqrt(pi) + (-2*a*t + 1)*(erf(sqrt(a)*sqrt(t)) - 1)*exp(a*t) + 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (sqrt(s) + sqrt(a)) ^ 2 / s, s, t)), "((2*t - 1/a)*exp(a*t)*erfc(sqrt(a)*sqrt(t)) + 1/a - 2*sqrt(t)/(sqrt(pi)*sqrt(a)))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (sqrt(s) + a) ^ 2 / sqrt(s), s, t)), "(-2*a*t*exp(a^2*t)*erfc(a*sqrt(t)) + 2*sqrt(t)/sqrt(pi))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / (sqrt(s) + a) ^ 3, s, t)), "(-a*t*(2*a^2*t + 3)*exp(a^2*t)*erfc(a*sqrt(t)) + 2*sqrt(t)*(a^2*t + 1)/sqrt(pi))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((sqrt(s) - a) / (s * (sqrt(s) + a)), s, t)), "(2*exp(a^2*t)*erfc(a*sqrt(t)) - 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((sqrt(s) - a) ^ 2 / (s * (sqrt(s) + a) ^ 2), s, t)), "(8*a^2*t*exp(a^2*t)*erfc(a*sqrt(t)) - 8*a*sqrt(t)/sqrt(pi) + 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((sqrt(s) - a) ^ 3 / (s * (sqrt(s) + a) ^ 3), s, t)), "(-8*a*sqrt(t)*(2*a^2*t + 1)/sqrt(pi) + (16*a^4*t^2 + 16*a^2*t + 2)*exp(a^2*t)*erfc(a*sqrt(t)) - 1)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(sqrt(s + a) / (s + b), s, t)), "(sqrt(a - b)*exp(-b*t)*erf(sqrt(t)*sqrt(a - b)) + exp(-a*t)/(sqrt(pi)*sqrt(t)))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s + b) / (s + a), s, t)), "exp(-a*t)*Heaviside(t)*erf(sqrt(t)*sqrt(-a + b))/sqrt(-a + b)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s ^ 2 + a ^ 2), s, t)), "Heaviside(t)*besselj(0, a*t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s ^ 2 - a ^ 2), s, t)), "Heaviside(t)*besseli(0, a*t)")
  expect_equal(mi_fmt(inverse_laplace_transform(3 / (sqrt(s) + a) ^ 4, s, t)), "3*(-2*a^3*t^(5/2)*(2*a^2*t + 5)/(3*sqrt(pi)) + t*(4*a^4*t^2 + 12*a^2*t + 3)*exp(a^2*t)*erfc(a*sqrt(t))/3)*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(sqrt(s) / (sqrt(s) + a) ^ 3, s, t)), "(-2*a*sqrt(t)*(a^2*t + 2)/sqrt(pi) + (2*a^4*t^2 + 5*a^2*t + 1)*exp(a^2*t)*erfc(a*sqrt(t)))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform(1 / sqrt(s) / (sqrt(s) + a) ^ 3, s, t)), "(-2*a*t^(3/2)/sqrt(pi) + t*(2*a^2*t + 1)*exp(a^2*t)*erfc(a*sqrt(t)))*Heaviside(t)")
  expect_equal(mi_fmt(inverse_laplace_transform((s ^ 2 * exp(2 * s) + 4 * exp(s) - 4) * exp(-2 * s) / (s * (s ^ 2 + 1)), s, t)), "cos(t)*Heaviside(t) + 4*cos(t - 2)*Heaviside(t - 2) - 4*cos(t - 1)*Heaviside(t - 1) - 4*Heaviside(t - 2) + 4*Heaviside(t - 1)")
})
